mm = utils.plugins.get('mmqgis')
res = {}
attrs = [a for a in dir(mm) if 'float' in a.lower() or 'text' in a.lower()]
res['attrs'] = attrs
for a_name in attrs:
    if a_name.endswith('_action'):
        ac = getattr(mm, a_name)
        res[a_name] = {'text': ac.text(), 'enabled': ac.isEnabled(), 'visible': ac.isVisible(),
                       'in_modify_menu': ac in mm.modify_menu.actions()}
    else:
        res[a_name] = repr(getattr(mm, a_name))[:150]
result = res"}
